// TH16 v1.00a Stage 3 mid-stage wave th16_s3_w01.
// Source: st03.ecl.txt MainSub00:1105-1152 (spawn schedule) with dependencies
// GirlA01:335-341, GirlA01F:343-362, GirlA01_at:364-411.
// Rank branch values are the source difficulty masks (E/N/H/L); target rank enum is
// 0=Easy..3=Lunatic and uses global(GVAR_RANK).

const TIME_LIMIT: int = 1100;
const OPENING_BUFFER: int = 120;

const TH16_RING_BALL: int = 448; // source etSprite(0, 6, 4)
const BULLET_COLOR: int = 4;

// Source GirlA01F (343-362): fly straight down, then curve toward the point
// (0,448) over 60 frames (mode 0 = linear), re-aim twice at +120/+240, then keep
// flying with the last stored velocity. GirlA01_at is started as async at entry.
async sub girl_main() {
    set_invuln(65535);
    // Source setHurtbox(24,24) -> circle r=12; setHitbox(16,16) -> circle r=8.
    set_hurtbox(12fx);
    set_hitbox(8fx);
    var aim0: angle = atan2(448fx - $self_y, 0fx - $self_x); // getAngle(%F2,FINAL_X,FINAL_Y,0,448)
    move_vel(0, 90deg, 1fx, EASE_LINEAR);                    // moveVel(pi/2, 1.0)
    move_vel(60, aim0, 1.3fx, EASE_LINEAR);                  // moveVelTime(60,0,F2,1.3)
    spawn girl_attack();                                     // @GirlA01_at() async
    wait(120);                                               // +120
    move_vel(60, aim_player(), 1.3fx, EASE_LINEAR);          // moveVelTime(60,0,ANGLE_PLAYER,1.3)
    wait(120);                                               // +240
    move_vel(60, aim_player(), 1.3fx, EASE_LINEAR);
    loop { wait(1000); }                                     // GirlA01F_324 wait(1000) loop
}

// Source GirlA01_at (364-411): wait 100, then etOn 1/5/5/5 times at 100-frame
// intervals (50 on Lunatic). Difficulty stack values:
//   etCount layers: E1 N1 H3 L3;  etSpeed s0: E1.5 N2.5 H3.5 L3.5, s1 = 1.2.
async sub girl_attack() {
    wait(100);
    var layers: int = 3;
    var s0: fx = 3.5fx;
    var interval: int = 100;
    var volleys: int = 5;
    var rank: int = global(GVAR_RANK);
    if rank == 0 { layers = 1; s0 = 1.5fx; volleys = 1; }
    if rank == 1 { layers = 1; s0 = 2.5fx; }
    if rank == 3 { interval = 50; }
    for k in 0..volleys {
        girl_volley(layers, s0);
        wait(interval);
    }
}

// One etOn of etAim(0,2) with etCount(0,5,layers), etAngle(0,0,0),
// etSpeed(0,s0,1.2) and etSprite(0,6,4): a 5-way player-aimed ring, layer q speed
// s0 + (1.2-s0)*q/(layers-1), delta 0. Native creation order is layer outer,
// way inner. The source EX ANIM record (a=1) keeps its birth backstep
// position -= 4*velocity, applied per bullet along its own angle.
sub girl_volley(layers: int, s0: fx) {
    var base: int = aim_player() as int;
    for q in 0..layers {
        var v: fx = s0;
        if layers > 1 { v = s0 + (1.2fx - s0) * (q as fx) / ((layers - 1) as fx); }
        for i in 0..5 {
            var ang: angle = (base + (i * 65536) / 5) as angle;
            _ = fire(TH16_RING_BALL, BULLET_COLOR,
                     $self_x - 4fx * v * cos(ang),
                     $self_y - 4fx * v * sin(ang),
                     v, ang, none, none);
        }
    }
}

// Source MainSub00 (1105-1152): four identical waves of five GirlA01 pairs at
// x = -/+16, -/+56 ... -/+176, y=-64, 10 frames apart; gaps 80/70/50 after the
// first three waves. The 6th enmCreate argument only selects the drop item and
// is omitted with rewards.
sub spawn_wave() {
    var a: fx = -16fx;
    for k in 0..5 {
        _ = spawn_enemy(a, -64fx, 130, 0, 1000, 0, girl_main);
        _ = spawn_enemy(-a, -64fx, 130, 0, 1000, 0, girl_main);
        a = a - 40fx;
        wait(10);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    spawn_wave();
    wait(80);
    spawn_wave();
    wait(70);
    spawn_wave();
    wait(50);
    spawn_wave();
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
